INSERT INTO agent_llm_call (
    id, run_id, user_id, phase, provider, model, credential_source, model_credential_id,
    prompt_tokens, completion_tokens, total_tokens, status, error_class, started_at, completed_at, latency_ms
)
VALUES (
    #{id}, #{runId}, #{userId}, #{phase}, #{provider}, #{model}, #{credentialSource}, #{modelCredentialId},
    #{promptTokens}, #{completionTokens}, #{totalTokens}, #{status}, #{errorClass},
    #{startedAt}, #{completedAt}, #{latencyMs}
)

INSERT INTO agent_tool_call (
    id, run_id, user_id, phase, tool_name, status, error_class, started_at, completed_at, latency_ms
)
VALUES (
    #{id}, #{runId}, #{userId}, #{phase}, #{toolName}, #{status}, #{errorClass},
    #{startedAt}, #{completedAt}, #{latencyMs}
)

mapper.select:
SELECT
    COALESCE(SUM(CASE WHEN r.credential_source = 'PLATFORM' THEN 1 ELSE 0 END), 0) AS platformRunCount,
    COALESCE(SUM(CASE WHEN r.credential_source = 'USER_KEY' THEN 1 ELSE 0 END), 0) AS userKeyRunCount,
    (
        SELECT COALESCE(SUM(CASE WHEN c.credential_source = 'PLATFORM' THEN 1 ELSE 0 END), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS platformLlmCallCount,
    (
        SELECT COALESCE(SUM(CASE WHEN c.credential_source = 'USER_KEY' THEN 1 ELSE 0 END), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS userKeyLlmCallCount,
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM agent_tool_call t
        WHERE t.user_id = #{userId}
    ) AS toolCallCount,
    (
        SELECT COALESCE(SUM(c.total_tokens), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
    ) AS knownTotalTokens,
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM agent_llm_call c
        WHERE c.user_id = #{userId}
          AND c.total_tokens IS NULL
    ) AS unknownTokenLlmCallCount
FROM agent_run r
WHERE r.user_id = #{userId}
